from PySide6.QtCore import Qt
from PySide6.QtGui import QFont
from PySide6.QtWidgets import QDialog, QVBoxLayout, QTabWidget, QTextBrowser, QPushButton

STYLE='''body { color:#643600; background:#fffaf2; font-family:"Yu Gothic UI", sans-serif; }
h2 { color:#b85d00; } h3 { color:#a35408; margin-top:20px; }
p,li { line-height:1.65; margin-bottom:12px; }
table { border-collapse:collapse; width:100%; }
th { background:#ffe0b0; } td,th { padding:10px; border:1px solid #e9bf88; }
'''
PAGES=[
('はじめに','''<h2>最初の設定</h2><ol>
<li><b>無線機 → 基本・無線機・Audio設定 → 基本設定</b><br>自局コール・運用場所・JCC/JCG・追加送信文を設定します。自局コールはメイン画面と共用です。</li>
<li><b>無線機タブで機種を選択</b><br>機種に応じて、下の無線機固有の設定が切り替わります。</li>
<li><b>CI-V／CAT設定を確認</b><br>ICOMのCI-Vアドレスは手修正できます。無線機本体に設定した値を使用してください。</li>
<li><b>COMポートを選択</b><br>番号とデバイス名で選べます。YaesuはEnhanced COMを使用します。</li>
<li><b>Audio IN／OUTを選択して保存</b><br>INは無線機→パソコンの受信音（LINE IN／マイク等）、OUTはパソコン→無線機の送信音です。INの初期値は未設定。選択済みなら起動時から入力し、無線機の接続とは独立して動作します。「自動」はWindowsの既定デバイス1つです。</li>
<li><b>接続テスト → 接続</b><br>テスト成功後、その下の［接続］を押して運用を開始します。テストだけでは運用接続は続きません。周波数表示・RXレベルを確認してください。</li>
<li><b>編集 → マクロ編集でテンプレートを選択</b><br>初期設定は通常交信です。RTTYコンテストではコンテスト用テンプレートを選び［反映］→保存。反映すると編集済みマクロも置き換わります。更新だけなら既存マクロは保持します。</li></ol>
<h3>コンテストでAuto CQを使う</h3><p>F1を指定回数送信します。初期10回、PTT解除後7秒待機。無線機への接続が必要です。詳細は「送信・Auto CQ」を参照してください。</p>'''),
('コントロール','''<h2>無線機を操作する</h2><p>周波数横の<b>［コントロール］</b>で開きます。1枚だけ表示し、もう一度押すとメイン画面の位置へ呼び戻します。</p>
<table><tr><th>操作</th><th>動作</th></tr>
<tr><td>バンドボタン</td><td>選択機種に対応したバンドを表示。「その他ICOM」は全候補です。起動中のバンド別最終周波数へ戻ります。初回はプリセット周波数です。</td></tr>
<tr><td>周波数を入力 → 設定／Enter</td><td>MHzで入力します。例：21.090700。表示は21.090.700 MHz、入力の小数点は1つです。</td></tr>
<tr><td>ジョグをつかんで回す</td><td>時計回りで＋、反時計回りで－。中心付近では回りません。</td></tr>
<tr><td>ホイール</td><td>標準は手前で＋、奥で－。「ホイール反転」で逆にできます。反転設定は保存されます。</td></tr>
<tr><td>＋／－ボタン</td><td>選択したSTEPずつ移動します。</td></tr></table>
<h3>STEP（初期10 Hz）</h3><table><tr><th>選択</th><th>1目盛りの変化</th></tr><tr><td>1 Hz</td><td>1 Hz</td></tr><tr><td>10 Hz</td><td>10 Hz</td></tr><tr><td>100 Hz</td><td>100 Hz</td></tr><tr><td>1 kHz</td><td>1,000 Hz</td></tr><tr><td>10 kHz</td><td>10,000 Hz</td></tr></table>
<h3>FILTER</h3><p>ICOMはFIL1／FIL2／FIL3を選びます。YaesuはWIDTHで帯域幅を選び、NARROWで狭帯域を切り替えます。現在の機種・モードに対応した候補を表示します。選択状態は無線機から取得し、非対応・未取得の操作は無効になります。</p><h3>NB・NR・NOTCH</h3><table><tr><th>操作</th><th>機能</th></tr><tr><td>NB</td><td>ノイズブランカーのON/OFF</td></tr><tr><td>NR</td><td>ノイズリダクションのON/OFF</td></tr><tr><td>NOTCH</td><td>自動／手動を選択してON/OFF</td></tr></table>
<p>状態は無線機から取得し、ON/OFFと色で表示します。「—」は未取得または非対応です。未接続・送信中・Auto CQ中は操作できません。</p>
<p>バンドのGはGHzです。周波数表示の単位は高いバンドでもMHzを維持します。</p>'''),
('受信・チューニング','''<h2>デコードを止める・再開する</h2><p>デコード枠の上辺右側にあるチェックは起動時ON。OFFでは文字のデコード、RXカード追加、CALLなどの自動取得を停止します。音声入力・スペクトラム・RXメーター・送信は継続します。既存カードは残り、ONに戻した時点から再開します。</p><p>カードは「時刻 RX | 内容」の1行表示で、長文は本文位置から折り返します。RXは濃い緑、TXは赤字と朱色のカードです。最大30件を表示します。</p><h3>デコードSQ（初期4）</h3><p>枠線上の「SQ」プルダウンでOFF・1～10を選びます。ノイズを文字として拾うのを抑える設定で、数値はdBではありません。設定は次回起動時にも保持します。</p><table><tr><th>設定・状況</th><th>使い方</th></tr><tr><td>OFF</td><td>SQによる抑制を解除。開始・終了ビットの確認は継続します。</td></tr><tr><td>1～10</td><td>1はOFFに近い弱い抑制です。2以降は段階的に強くなります。まずは4から試してください。</td></tr><tr><td>ゴミ文字が多い</td><td>SQを上げます。狭いフィルターを通したノイズでは高めの設定が必要な場合があります。</td></tr><tr><td>信号があるのに読めない</td><td>受信位置を確認し、SQを下げます。上げすぎると弱い信号を取りこぼします。</td></tr></table><p>表示感度スライダーは波形の見た目だけを変え、SQやデコード感度には影響しません。SQは文字のデコードを抑制します。音声入力・スペクトラム・RXメーターは継続します。短い「599」などを文字数で削除する機能ではありません。</p><h2>RTTYの受信位置を合わせる</h2><p>波形上端の短いグレー線はMARKとSPACEの中心です。下のCenterには2本の平均周波数を表示し、受信位置・シフト幅の変更に連動します。</p>
<table><tr><th>操作</th><th>動作</th></tr>
<tr><td>スペクトラムをクリック</td><td>クリック位置へMARKを移動。SPACEも間隔を保って移動します。</td></tr>
<tr><td>MARK／Center／SPACEの線をドラッグ</td><td>どの線をつかんでもMARKとSPACEが間隔を保って一緒に移動します。Centerは上端の短いグレー線付近をつかみます。</td></tr>
<tr><td>シフト幅を入力</td><td>MARKを保ってSPACEを移動します。AUTO TUNEもこの幅を基準にします。</td></tr>
<tr><td>AUTO TUNE</td><td>設定幅の許容範囲内で2つのピークを探します。実際のピークに合わせるため、幅が少し変わることがあります。ノイズにも反応するので結果を確認してください。</td></tr>
<tr><td>幅RESET</td><td>位置を保って幅を170 Hzへ戻します。</td></tr>
<tr><td>位置RESET</td><td>幅を保ってMARKを2125 Hzへ戻します。</td></tr></table>
<p>通常の標準位置はMARK 2125 Hz／SPACE 2295 Hz。ここで動かすのは音声のデコード位置です。無線機の周波数を動かすにはコントロールを使います。</p>
<h3>クロススコープ</h3><p>上部のコントロール右にある「クロススコープ」で、別ウィンドウの表示を切り替えます。MARKは横長、SPACEは縦長の楕円として表示します。縦横にそろい、線に近い細い楕円になる状態が同調の目安です。周波数がずれると楕円が傾き、ノイズや信号の切り替わりで輪郭が乱れます。片方の音が続く間は楕円も片方だけになります。表示は毎秒5回更新し、切り替わり途中を抑えて安定した短い区間を描きます。各方向で最新と1つ前の輪を保持し、最大約0.7秒で薄く消します。1つ前の輪はさらに薄く表示します。縦横合わせて最大4本で、新しい輪が届けば最も古い輪を置き換えます。受信位置変更・入力停止・非表示時には残光を消します。周波数はスペクトラムのMARK／SPACEに追従します。主画面の幅は変わらず、接続やデコードも継続します。×またはEscで閉じるとボタンもOFFになります。</p><p>受信音から描く補助表示で、校正された信号計ではありません。ノイズでも軌跡が出ます。SQ・デコードチェック・スペクトラムの表示感度とは独立しています。起動時はOFFです。</p><h3>波形の高さと入力音量</h3><p>グラフの中央より少し上にある<b>黄土色の横線</b>が、表示調整の目安です。信号の山がこの線に届くか、少し越える程度になるように<b>表示感度</b>を調整すると、山の位置を見分けやすくなります。目安線はデコード可能かを判定する線でも、SQのしきい値でもありません。</p><p>縦軸は固定基準で、少し平均化して表示します。<b>表示感度</b>は波形の高さだけを調整し、デコード・受信音量には影響しません。入力音量はAudio設定の受信レベルで調整します。</p>'''),
('送信・Auto CQ','''<h2>マクロと手動送信</h2><p>F1～F9または画面のマクロボタンで送信します。手動送信は入力欄へ記入し［TX］。<b>STOP／Esc</b>で停止できます。右上・右下のSTOPはどちらもマクロ・手動送信・Auto CQを停止します。音声終了とPTT解除を待って再送信できます。中断した送信は自動ログに追加しません。</p>
<h3>コンテスト用テンプレート</h3><p>マクロ編集のF9下に、選択したテンプレートの設定案内を青字で表示します。選択だけではマクロやSENTは変わりません。［反映］でSENTも初期設定（通常は空欄、JARL WWは01、CQ WWは25、すべて固定ON）になります。保存ボタンの上で編集でき、［保存］でメイン画面にも反映します。［反映］→保存で適用します。</p><table><tr><th>テンプレート</th><th>SENT（固定ON）</th></tr><tr><td>JARL World Wide RTTY</td><td>開始時の年齢、または01（00・99も可）。マルチオペで年齢を送る場合は平均年齢。</td></tr><tr><td>CQ WW RTTY DX</td><td>運用地のCQゾーン。日本国内は25（小笠原・南鳥島を除く）。</td></tr></table><p>599はマクロに含まれるのでSENTには入力しません。01などの先頭の0は保持します。CQ WW用を適用すると、受信番号の州・地域略号もRCVDへ取り込みます（例：05 MA）。取り込み結果は確認・修正できます。</p><h3>Auto CQ</h3><table><tr><th>項目</th><th>内容</th></tr><tr><td>内容</td><td>F1のマクロを繰り返し送信</td></tr><tr><td>回数</td><td>初期10回、1～99回</td></tr><tr><td>間隔</td><td>初期7秒、PTT解除後に待機、1～99秒</td></tr><tr><td>入力補正</td><td>99超は99、1未満は1、数字以外・空欄は初期値に戻します。</td></tr><tr><td>中止</td><td>STOP／Esc／他のマクロ</td></tr></table>
<h3>未接続でのテスト</h3><p>「未接続でもMACROと手動送信可」は起動時OFF。ONならPTTを操作せずAudio OUTへ音声を出します。未接続でも自動ログON・相手CALLあり・TU 73／TU73の正常送信完了でログへ追加します。周波数を取得できない場合はADIFのFREQ・BANDを空欄（項目省略）で記録します。<b>Auto CQは常に接続必須</b>です。</p>'''),
('QSO・ログ','''<h2>QSOの完了と保存</h2><p>自分の送信文に「TU 73」または「TU73」があると、正常送信完了後に自動ログ追加を判定します。マクロ・手動送信とも対象です。受信文は対象外です。旧「QSO完了」チェックの設定は不要です。TUだけ・73だけでは追加しません。</p>
<table><tr><th>TU 73送出で自動ログ追加</th><th>正常送信終了後</th></tr><tr><td>ON</td><td>相手CALLがあればログ追加。自動日時なら送信完了時の現在日時、日時手動なら指定日時を使います。</td></tr><tr><td>OFF</td><td>自動追加しません。手動で［ログに追加］を押します。</td></tr></table>
<p>停止・送信失敗では自動追加しません。無線機の接続状態は自動ログ追加の条件にしません。送信中にQSO欄や周波数を変更した場合も対象外です。</p>
<p>日付（YYYY-MM-DD）と時刻（HH:MM）は現在日時を常時表示します。自動中は編集不可で、コロンが2秒点灯・2秒消灯します。「日時手動」をONにすると更新を止め、編集できます。OFFで現在日時へ戻ります。日付が変われば自動で更新します。JSTで表示し、ADIFにはUTCで保存します。手動で片方だけ入力した場合は両方を入力してください。日時手動がOFFなら現在日時を使います。保存成功後は日時が自動に戻り、相手CALL・RCVDが空になります。保存失敗時は入力を保持します。</p>
<p>送信中は受信文字の取り込みとCALL・RST・受信番号の自動取得を止め、ノイズによる入力変更を防ぎます。手動編集・周波数変更があれば自動追加を見送り、理由をステータス欄と通信記録へ表示します。日時の自動更新や点滅は手動編集として扱いません。</p><h3>最新QSO</h3><p>表をダブルクリックするとQSOログが開きます。</p><p>広い画面では左右2列、狭い画面では1列です。月別ADIFをファイル名順、その中を記録順に数えたNo.を表示し、大きい番号から左上→右上→次の行へ並びます。日時を修正しても記録順を優先します。右下の枠線上には全ログの合計件数を表示します。削除後は番号を詰め直します。表示メニューの2／4／6／8／10件（初期4件）は左右合計の件数です。</p><h3>SENT</h3><p>固定は初期ON。OFFではログ追加成功時に数字を＋1します（001→002）。文字列・空欄は保持。通常交信のSENTは空欄でも構いません。</p>
<h2>日時とログ</h2><p>画面の日時・手動入力・最新QSO・QSOログ・生ログはJST固定です。PCの時計を使用しますが、PCのタイムゾーン設定には依存しません。ADIFの交信日時と月別ファイルはUTC基準です。例えばJST 10月1日00:30の交信はUTC 9月30日15:30となり、202609.adiに保存します。過去の日時を手動入力した場合も交信のUTC年月で保存します。「今月のADIF」は現在のUTC年月、「今日の生ログ」は現在のJST日付のファイルを開きます。</p><h3>ログファイルとバックアップ</h3><p>ADIFは交信日時のUTC年月ごとのYYYYMM.adiへ追記します。生ログTXTはJST日付ごとのYYYYMMDD_all.txtです。メニューにはUTC基準／JST基準を明記し、クリック時の月・日のファイルを開きます。以前のログを自動で再分配することはありません。</p><p>編集 → バックアップ設定で、終了時（初期ON）・QSOログの指定件数ごと（初期OFF、30件）を設定できます。件数は新しく保存できたQSOを数え、再起動後も引き継ぎます。編集・削除では増えません。［いますぐバックアップ］はチェック状態に関係なく実行できます。</p><p>ADIFと生ログTXTをまとめてlogdata/backupsへZIP保存します。過去のバックアップはZIPに含めません。バックアップ成功で件数を0に戻し、失敗時は件数と元ログを保持して通知します。設定変更は保存、キャンセルは変更を破棄します。手動バックアップはキャンセルしても残ります。</p><h3>ログ一覧の編集・削除</h3><p><b>表示 → QSOログ</b>で保存済みADIFを表示。BANDは「15m / 21MHz」のように併記します。</p>
<p>行選択→［編集］またはダブルクリックで日時・CALL・周波数・RST・SENT・RCVDを修正。［削除］は対象を確認して実行します。変更前のADIFはlogdata/backupsへ保存し、メインの最新QSOにも反映します。</p>
<p>通常交信のQTH / INFOは {MYQTH} {MYJCCJCG} と {MYTXT} を使います。追加送信文には名前なども設定できます。</p>'''),
('Cabrillo出力','''<h2>コンテスト提出用ファイルを作る</h2><p><b>ファイル → Cabrillo出力</b>で開きます。汎用・JARL World Wide RTTY・CQ WW RTTY DXから選びます。</p><ol><li><b>出力形式</b>を選択します。</li><li><b>対象QSO</b>を抽出します。専用形式では開催年から大会期間を入力できます。大会期間は現在の開催ルールからの計算値です。公式日程を確認し、異なれば開始・終了を修正してください。JST／UTCを切り替えて確認し、出力する行にチェックします。日時・周波数・CALL・RST・SENT・RCVDは出力用に修正できます。元のADIFは変わりません。</li><li><b>提出情報</b>を入力します。参加部門・自局CALLなどの必須項目、条件付き項目、任意項目を表示します。氏名・住所はローマ字で入力してください。</li><li><b>プレビュー</b>で内容と確認事項を確認し、［ファイルに保存］で保存先を選びます。保存先フォルダーも開けます。</li></ol><p>日時の表示・入力は分単位です。抽出は開始の分の先頭から、終了の分の末尾まで含みます。汎用形式の初期開始はJSTの今月1日00:00です。元ADIFの秒は保持します。</p><p>入力に不備がある場合は、該当セルを薄い赤で示し、修正方法を案内します。技術的な詳細はvar/cabrillo_YYYYMMDD.logへ記録します。</p><h3>交換番号と送信機番号</h3><p>JARLは年齢または01（00・99も可）。CQ WWはCQゾーンを入力し、米国・カナダ局には州・地域略号も必要です（例：05 MA）。その他の運用地はDXを出力します。米国・カナダ系コールで対象外地域から運用する場合はDXを明記できます。</p><p>CQ WWのMULTI-ONE／MULTI-TWOは各QSOにTX番号0／1を入力してください。選択した複数行へまとめて設定できます。採点対象外として残す交信はX-QSOをチェックします。</p><h3>入力の保持と保存</h3><p>［戻る］でも入力は残ります。抽出条件を変えたら［抽出］を押します。［ADIF再読込］は確認後に出力用編集を破棄します。入力不足は修正して再確認、保存失敗は保存先を変更して再試行できます。正常保存した提出情報は次回も利用できます。</p><p>出力はCabrillo 3.0、ASCII、CRLF、UTC、RTTYのRY表記です。ADIFや生ログへの上書きは防止します。得点は自動計算せず、申告得点が空欄なら省略します。ログ提出サイトへの送信は行いません。</p><p>汎用形式では大会識別名とQSO項目の並びを指定します。提出先固有の並び・必要項目は確認してください。専用形式も提出先の確認結果に従って修正できます。</p>'''),
('機種別補足','''<h2>ICOM</h2><p>Ver0.77追加：IC-7200 / IC-7410 / IC-7600 / IC-9100（資料確認済み・実機未確認）。USB音声入出力は別途選択してください。DATA時の変調入力を無線機側でUSBに設定します。IC-7600はD1を使用するため、DATA1の変調入力をUSBに設定します。IC-9100は運用するMAIN側を本体で選択してください。これら４機種のフィルター切替は無線機本体で行います。</p><p>無線機本体のCI-Vアドレスと一致させます。IC-7300MK2をIC-7300のアドレスで運用している場合なども、手入力した設定をそのまま使用できます。</p>
<h2>Yaesu（試験用）</h2><p>FT-991/A・FTX-1は実機未確認です。DATA入力はUSB、CAT RTSはDISABLE（OFF）。FT-991/AはVFO A、FTX-1はMAINを送信側にします。FTX-1はCAT対応ファームウェアが必要です。</p>
<h3>接続ボタン</h3><p>画面左上の［未接続］で接続、青い［接続］で切断します。接続中は連打できません。機種とCOMポートはボタンにマウスを重ねると確認できます。</p><h3>接続の応答確認</h3><p>時間経過だけでは切断しません。周波数の応答取得に3回連続で失敗したときに切断します。途中で応答が戻れば接続を維持します。切断理由と日時はステータス表示・接続表示のツールチップ・運用記録に残します。音声入力は継続します。</p><h3>起動とバージョンアップ</h3><p>起動時にログフォルダーへ一時ファイルを作成・書き込み・削除して確認します。作成や書き込みができない場合は対象パスと理由を表示し、メイン画面を開かず終了します。</p><p>同じフォルダーのPSRTTYは二重起動できません。起動済みならその画面を呼び戻します。</p><p><b>ヘルプ → PSRTTYのバージョンアップ</b>で配布ZIPを選択します。設定・ログをバックアップして更新し、再起動します。開発用のPATCH.zipは指定できません。</p>''')]


class GuideWindow(QDialog):
    def __init__(self,parent=None):
        super().__init__(parent,Qt.Window); self.setWindowTitle('初期設定ガイド')
        self.resize(900,680); self.setMinimumSize(600,420)
        root=QVBoxLayout(self); self.tabs=QTabWidget(); root.addWidget(self.tabs)
        for title,body in PAGES:
            browser=QTextBrowser(); font=QFont(); font.setPointSize(11); browser.setFont(font)
            browser.document().setDefaultStyleSheet(STYLE)
            browser.setHtml(body); self.tabs.addTab(browser,title)
        close=QPushButton('閉じる'); close.clicked.connect(self.hide); root.addWidget(close)
